def _et(bars):
    """Minute-of-day, session index, weekday and day-of-month, in New York.

    Bars carry UTC timestamps; every calendar rule here is a New York rule, so
    the offset has to be resolved per bar rather than assumed."""
    import datetime
    mins = []
    sess = []
    dow = []
    dom = []
    last = None
    s = -1
    for b in bars:
        ts = str(b["t"])
        y = int(ts[0:4]); mo = int(ts[5:7]); d = int(ts[8:10])
        hh = int(ts[11:13]); mi = int(ts[14:16])
        if mo < 3 or mo > 11:
            dst = False
        elif 3 < mo < 11:
            dst = True
        elif mo == 3:
            w = datetime.date(y, 3, 1).weekday()
            dst = d >= 1 + ((6 - w) % 7) + 7
        else:
            w = datetime.date(y, 11, 1).weekday()
            dst = d < 1 + ((6 - w) % 7)
        t = (datetime.datetime(y, mo, d, hh, mi)
             - datetime.timedelta(minutes=240 if dst else 300))
        key = (t.year, t.month, t.day)
        if key != last:
            last = key
            s += 1
        mins.append(t.hour * 60 + t.minute)
        sess.append(s)
        dow.append(t.weekday())
        dom.append(t.day)
    return mins, sess, dow, dom


def _strike(px):
    inc = 1.0 if px < 25.0 else (2.5 if px < 200.0 else 5.0)
    return round(px / inc) * inc, inc


def family_init(ctx):
    bars = ctx.bars
    n = len(bars)
    mins, sess, dow, dom = _et(bars)
    daily = len(set(str(b["t"])[:10] for b in bars)) == n
    if daily:
        mins = [955] * n

    emin = int(ctx.p.entry_min)
    frac = float(ctx.p.pin_frac)
    drag = float(ctx.p.drag)
    lb = max(1, int(ctx.p.lb))
    monthly = int(ctx.p.monthly_only)

    order = []
    sclose = {}
    swd = {}
    sdom = {}
    first_rth = {}
    for j in range(n):
        if not (570 <= mins[j] < 960):
            continue
        s = sess[j]
        if s not in sclose:
            order.append(s)
            swd[s] = dow[j]
            sdom[s] = dom[j]
            first_rth[s] = j
        sclose[s] = float(bars[j]["c"])
    pos = dict((s, k) for k, s in enumerate(order))

    ev = [False] * n
    seen = set()
    for j in range(n):
        s = sess[j]
        if s in pos and mins[j] >= emin and s not in seen:
            seen.add(s)
            ev[j] = True

    sig = [0] * n
    for k, s in enumerate(order):
        if swd[s] != 4:
            continue
        if monthly and not (15 <= sdom[s] <= 21):
            continue
        if k - lb < 0 or k + 1 >= len(order):
            continue
        p = sclose[s]
        kk, g = _strike(p)
        if abs(p - kk) > frac * (g / 2.0):
            continue
        p5 = sclose[order[k - lb]]
        if abs(p5 - kk) < drag * g:
            continue
        j = first_rth[order[k + 1]] - 1        # fills at the next session's open
        if j < 0 or j <= first_rth[s]:
            continue
        sig[j] = 1 if p5 > kk else -1

    sidx = [-1] * n
    for j in range(n):
        s = sess[j]
        if s in pos:
            sidx[j] = pos[s]

    ctx.sig = ctx.series(sig, "pin_rel")
    ctx.ev = ctx.series(ev, "pr_eval")
    ctx.sk = ctx.series(sidx, "pr_session")


def signal(ctx, i):
    return int(ctx.sig[i])


def exit_signal(ctx, i):
    """The distortion is a dated thing: out at the close of the hold-th session."""
    if not ctx.positions:
        return False
    e = min(p["entry_i"] for p in ctx.positions)
    k = ctx.sk[i]
    ke = ctx.sk[e]
    if k < 0 or ke < 0:
        return False
    return (k - ke) >= int(ctx.p.hold) and bool(ctx.ev[i])
